{{ (() => {
  const naytaMa = (typeof naytaMaaraajat !== 'undefined') ? naytaMaaraajat.isSwitchedOn : false;
  const evs = (haeKalenteri.data || []).filter(e => naytaMa || e.lahde !== 'maaraaika');
  const ank = appsmith.store.kuuAnkkuri || moment().format('YYYY-MM-DD');
  const alku = moment(ank).startOf('month');
  const alkuRuudukko = alku.clone().subtract((alku.day() + 6) % 7, 'days');
  const tanaan = moment().format('YYYY-MM-DD');
  const kuu = alku.format('M');
  const esc = (s) => String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
  const paivittain = {};
  evs.forEach(e => { (paivittain[e.pvm] = paivittain[e.pvm] || []).push(e); });
  let solut = '';
  for (let i = 0; i < 42; i++) {
    const d = alkuRuudukko.clone().add(i, 'days');
    const iso = d.format('YYYY-MM-DD');
    const lista = paivittain[iso] || [];
    let chips = '';
    lista.forEach(e => {
      const aika = e.alkaa ? (esc(e.alkaa) + ' ') : '';
      const kohde = e.merkinta_id ? ('merkinta:' + e.merkinta_id) : ('tyo:' + e.toimeksianto_id);
      const vihje = esc(e.otsikko + (e.lisatieto ? (' - ' + e.lisatieto) : ''));
      const lisa = e.lisatieto ? '<div class="lisa">' + esc(e.lisatieto) + '</div>' : '';
      chips += '<div class="chip" data-kohde="' + kohde + '" title="' + vihje + '" style="border-left-color:' + esc(e.vari) + '">' + '<div class="rivi">' + aika + esc(e.otsikko) + '</div>' + lisa + '</div>';
    });
    const lk = 'solu' + (d.format('M') !== kuu ? ' himmea' : '') + (iso === tanaan ? ' tanaan' : '');
    solut += '<div class="' + lk + '" data-pvm="' + iso + '"><div class="pv">' + d.format('D') + '</div>' + chips + '</div>';
  }
  const otsikot = ['ma','ti','ke','to','pe','la','su'].map(x => '<div class="otsikko">' + x + '</div>').join('');
  return '<!doctype html><html><head><meta charset="utf-8"><style>'
    + '*{box-sizing:border-box}body{margin:0;font-family:-apple-system,Segoe UI,Roboto,Arial,sans-serif;font-size:12px;color:#111827;background:#fff}'
    + '.ruudukko{display:grid;grid-template-columns:repeat(7,1fr);gap:1px;background:#E5E7EB;border:1px solid #E5E7EB}'
    + '.otsikko{background:#F9FAFB;padding:6px 8px;font-weight:600;color:#6B7280;text-transform:uppercase;letter-spacing:.04em}'
    + '.solu{background:#fff;min-height:96px;padding:4px 5px;cursor:pointer}'
    + '.solu:hover{background:#F9FAFB}'
    + '.himmea .pv{color:#D1D5DB}.himmea{background:#FCFCFD}'
    + '.tanaan{outline:2px solid #B91C1C;outline-offset:-2px}'
    + '.pv{font-weight:600;color:#374151;margin-bottom:3px}'
    + '.chip{border-left:3px solid #999;background:#F3F4F6;border-radius:3px;padding:2px 5px;margin-bottom:2px;'
    + 'overflow:hidden;cursor:pointer;line-height:1.25}'
    + '.chip:hover{background:#E5E7EB}'
    + '.chip .rivi,.chip .lisa{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}'
    + '.chip .lisa{color:#6B7280;font-size:10px}'
    + '.lg{display:flex;flex-wrap:wrap;gap:14px;padding:8px 2px;color:#6B7280}'
    + '.lg span{display:inline-flex;align-items:center;gap:5px}'
    + '.lg i{width:10px;height:10px;border-radius:2px;display:inline-block}'
    + '</style></head><body><div class="ruudukko">' + otsikot + solut + '</div>'
    + '<div class="lg">'
    + '<span><i style="background:#15803D"></i>Valmistuu</span>'
    + '<span><i style="background:#1D4ED8"></i>Asennus</span>'
    + (naytaMa ? '<span><i style="background:#B45309"></i>Vastattava</span>' : '')
    + (haeLajit.data || []).map(l => '<span><i style="background:' + esc(l.vari) + '"></i>' + esc(l.nimi) + '</span>').join('')
    + '</div>'
    + '<script>document.addEventListener("click", function(ev){'
    + 'var c = ev.target.closest(".chip");'
    + 'if (c) { parent.postMessage(c.getAttribute("data-kohde"), "*"); ev.stopPropagation(); return; }'
    + 'var s = ev.target.closest(".solu");'
    + 'if (s) { parent.postMessage("pvm:" + s.getAttribute("data-pvm"), "*"); }'
    + '});<\/script></body></html>';
})() }}
